#pragma once
#include <stdint.h>

// Half-block icon data generated by convert_assets.py
// Each icon: 6 cells wide x 4 cells tall = 24 cells

struct HalfBlockIcon {
    const char* chars;      // 24 char codes (6x4)
    const uint8_t* fg;      // 24 foreground color indices
    const uint8_t* bg;      // 24 background color indices
    const char* label;
};

